/* projects */
async function openProject(p){stopAll();P=migrate(p);st.sel=0;st.disp={};st.fx=[];await DB.put('projects',P.id,P);localStorage.setItem('dm3-last',P.id);loadLogoImg();renderControl();renderProjects()}
function cloneEpisode(src){const p=JSON.parse(JSON.stringify(src));p.id=uid();p.created=Date.now();p.updated=Date.now();p.segments.forEach(s=>{s.id=uid();s.lines.forEach(l=>l.id=uid())});p.game=freshGame();return p}
async function importEpisodeJSON(j){if(j.audio||j.voices){await installPackObj(j.voices||{items:j.audio})}const src=j.project||j.episode||j;if(!src.segments)throw new Error('bad');await openProject(cloneEpisode(migrate(src)));toast('قسمت وارد شد');showView('control')}
$('#newTpl').onclick=async()=>{await openProject(migrate(defaultEpisode()));toast('قسمت جدید از قالب بانک زمان ساخته شد');showView('control')};
$('#newBlank').onclick=async()=>{const p=defaultEpisode();p.name='قسمت جدید';p.brief=null;p.segments=[mkSeg({type:'title',title:'داداش‌مود',subtitle:'قسمت جدید'})];await openProject(migrate(p));showView('script')};
$('#projList').addEventListener('click',async e=>{const b=e.target.closest('[data-pa]');if(!b)return;const id=b.closest('[data-pid]').dataset.pid;const p=await DB.get('projects',id);const a=b.dataset.pa;
  if(a==='open'){await openProject(p);showView('control')}
  else if(a==='dup'){const c=cloneEpisode(p);c.name=p.name+' · نسخهٔ جدید';await DB.put('projects',c.id,c);toast('کپی ساخته شد (صداهای یکسان خودکار دوباره استفاده می‌شوند)؛ سناریوی ویدیوی بعدی را به آن بدهید',4500);renderProjects()}
  else if(a==='exp'){const prev=P;P=migrate(JSON.parse(JSON.stringify(p)));const voices=await voicePackObj();P=prev;const out={format:'dadashmode-project/3',project:p,voices};download(new Blob([JSON.stringify(out)],{type:'application/json'}),safeName(p.name)+'.dadashmode.json')}
  else if(a==='del'){if(p.id===P.id){toast('قسمت باز را نمی‌شود حذف کرد');return}if(b.dataset.armed!=='1'){b.dataset.armed='1';b.textContent='مطمئنید؟';setTimeout(()=>{b.dataset.armed='';b.textContent='حذف'},2500);return}await DB.del('projects',id);renderProjects()}});
$('#importProj').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{await importEpisodeJSON(JSON.parse(await f.text()))}catch(err){console.error(err);toast('فایل قسمت معتبر نیست')}e.target.value=''};
$('#takes').addEventListener('click',async e=>{const b=e.target.closest('[data-ta]');if(!b)return;const row=b.closest('[data-tid]');const t=await DB.get('takes',row.dataset.tid);const a=b.dataset.ta;
  if(a==='view'){let v=row.querySelector('video');if(!v){v=document.createElement('video');v.controls=true;v.playsInline=true;v.src=URL.createObjectURL(t.blob);row.firstElementChild.appendChild(v)}v.play()}
  else if(a==='dl')download(t.blob,t.name);else if(a==='srt')download(new Blob([t.srt],{type:'text/plain;charset=utf-8'}),t.name.replace(/\.\w+$/,'.srt'));
  else if(a==='share'){const file=new File([t.blob],t.name,{type:t.blob.type});if(navigator.canShare&&navigator.canShare({files:[file]})){try{await navigator.share({files:[file],title:t.name})}catch(err){}}else{download(t.blob,t.name);toast('اشتراک مستقیم پشتیبانی نشد؛ فایل دانلود شد تا در فضای ابری آپلود کنید',4500)}}
  else if(a==='del'){if(b.dataset.armed!=='1'){b.dataset.armed='1';b.textContent='مطمئنید؟';setTimeout(()=>{b.dataset.armed='';b.textContent='حذف'},2500);return}await DB.del('takes',t.id);renderTakes()}});
/* settings */
const bindS=(sel,key,kind)=>$(sel).addEventListener('change',e=>{S[key]=kind==='bool'?e.target.checked:kind==='num'?+e.target.value:e.target.value.trim();saveS();if(key==='quality')setQuality();if(AE.ctx){AE.sfx.gain.value=S.sfxVol;AE.voice.gain.value=S.voiceVol}if(key==='normalize')BUF.clear();renderSettings();renderPreflight()});
bindS('#sProv','aiProvider');bindS('#sGKey','geminiKey');bindS('#sGChat','geminiChat');bindS('#sGTts','geminiTts');bindS('#sOKey','openaiKey');bindS('#sOBase','openaiBase');bindS('#sOChat','openaiChat');bindS('#sOTts','openaiTts');
bindS('#sQual','quality');bindS('#sFps','fps','num');bindS('#sAutoDl','autoDl','bool');bindS('#sDevTts','devTts','bool');bindS('#sNorm','normalize','bool');bindS('#sBed','musicBed','bool');bindS('#sWake','wake','bool');bindS('#sSfx','sfxVol','num');bindS('#sVoice','voiceVol','num');
$$('[data-show]').forEach(b=>b.onclick=()=>{const i=$('#'+b.dataset.show);i.type=i.type==='password'?'text':'password'});
$('#pickFolder').onclick=pickFolder;
$('#sTest').onclick=async()=>{['geminiKey:#sGKey','openaiKey:#sOKey','openaiBase:#sOBase'].forEach(x=>{const[k,s]=x.split(':');S[k]=$(s).value.trim()});saveS();$('#sTestOut').textContent='در حال تست...';
  try{const j=await aiJSON('Reply with JSON {"ok":true,"msg":"<a short friendly Persian greeting>"}','test');$('#sTestOut').textContent='اتصال متن برقرار است ✓ '+(j.msg||'')}catch(e){$('#sTestOut').textContent=e.message}};
function renderNet(){const on=navigator.onLine;const el=$('#net');el.textContent=on?'آنلاین':'آفلاین · نمایش ادامه دارد';el.className='net '+(on?'on':'off')}
window.addEventListener('online',renderNet);window.addEventListener('offline',renderNet);

/* ---------------- boot ---------------- */
async function boot(){icons();renderSfx();renderNet();await DB.open();for(const r of await DB.all('audio'))AUD.set(r.key,r);
  const last=localStorage.getItem('dm3-last');let p=last&&await DB.get('projects',last);if(!p){const all=await DB.all('projects');p=all[0]}
  if(!p){p=migrate(defaultEpisode());await DB.put('projects',p.id,p)}P=migrate(p);localStorage.setItem('dm3-last',P.id);
  setQuality();loadLogoImg();renderControl();requestAnimationFrame(frame);
  try{await Promise.all(['900 40px Vazirmatn','800 40px Vazirmatn','40px Lalezar','900 40px Estedad','900 40px "Noto Kufi Arabic"','700 40px Marhey'].map(f=>document.fonts.load(f,'سلام ۱۲۳')));st.fonts=document.fonts.check('40px Lalezar','سلام')}catch(e){st.fonts=false}
  const n=await loadInstalledPack();if(n){toast(fa(n)+' صدا از بستهٔ نصبی کنار اپ نصب شد');refreshVoiceBits()}renderPreflight();
  if(window.speechSynthesis)speechSynthesis.onvoiceschanged=()=>{if(!$('#view-voice').classList.contains('hidden'))renderVoice()};
  document.addEventListener('visibilitychange',()=>{if(document.hidden&&st.rec)toast('حین ضبط این تب را باز نگه دارید')});
  if('serviceWorker' in navigator&&location.protocol.startsWith('http')){try{await navigator.serviceWorker.register('sw.js');navigator.serviceWorker.addEventListener('controllerchange',()=>renderPreflight())}catch(e){console.warn(e)}}
}
